"""
Offline endpoint-aligned robust piecewise-affine trend estimator.

The enhanced estimator is fit over the complete supplied sequence and then
returns samples aligned to input indices window_size-1 through the endpoint.
"""
import numpy as np

try:
    from scipy.signal import savgol_filter
    _HAVE_SCIPY = True
except Exception:
    _HAVE_SCIPY = False


def adaptive_filter(x, window_size=20):
    x = np.asarray(x, dtype=float)
    if x.ndim != 1:
        raise ValueError("Input signal must be one-dimensional")
    if len(x) < window_size:
        raise ValueError("Input signal length must be >= window_size")
    return np.mean(np.lib.stride_tricks.sliding_window_view(x, window_size), axis=1)


def _finite_signal(x):
    x = np.asarray(x, dtype=float).copy()
    ok = np.isfinite(x)
    if not np.any(ok):
        return np.zeros_like(x)
    if not np.all(ok):
        ii = np.arange(x.size)
        x[~ok] = np.interp(ii[~ok], ii[ok], x[ok])
    return x


def _fallback_smoother(x, span):
    x = np.asarray(x, dtype=float)
    if span <= 1:
        return x.copy()
    k = np.ones(span, dtype=float) / float(span)
    left = span // 2
    right = span - 1 - left
    return np.convolve(np.pad(x, (left, right), mode="reflect"), k, mode="valid")


def _piecewise_linear_filter(x, window_size):
    """Bounded dynamic-programming fit of penalized affine regimes."""
    x = np.asarray(x, dtype=float)
    n = x.size
    try:
        if n <= 2:
            return x.copy()

        radius = max(1, min(2, int(window_size) // 8))
        y = _fallback_smoother(x, 2 * radius + 1)

        d = np.diff(x)
        dmed = float(np.median(d)) if d.size else 0.0
        sigma = float(np.median(np.abs(d - dmed)) / 0.6745)
        sigma = max(sigma, np.finfo(float).eps)
        beta = 3.2 * sigma * sigma * np.log(float(n) + 1.0)

        stride = max(1, int(np.ceil(float(n) / 600.0)))
        nodes = np.arange(0, n, stride, dtype=np.int64)
        if nodes.size == 0 or nodes[-1] != n - 1:
            nodes = np.r_[nodes, n - 1]
        nodes = np.unique(nodes)
        if nodes.size > 600:
            nodes = np.unique(np.r_[nodes[:599], n - 1])
        m = int(nodes.size)
        min_len = max(3, int(window_size) // 3)

        t = np.arange(n, dtype=float)
        py = np.r_[0.0, np.cumsum(y)]
        pty = np.r_[0.0, np.cumsum(t * y)]
        pt = np.r_[0.0, np.cumsum(t)]
        pt2 = np.r_[0.0, np.cumsum(t * t)]
        py2 = np.r_[0.0, np.cumsum(y * y)]
        eps = np.finfo(float).eps

        def segment_cost(a, b):
            count = float(b - a + 1)
            st = pt[b + 1] - pt[a]
            st2 = pt2[b + 1] - pt2[a]
            sy = py[b + 1] - py[a]
            sty = pty[b + 1] - pty[a]
            sy2 = py2[b + 1] - py2[a]
            den = count * st2 - st * st
            if den <= eps:
                slope = 0.0
                intercept = sy / count
            else:
                slope = (count * sty - st * sy) / den
                intercept = (sy - slope * st) / count
            sse = sy2 - intercept * sy - slope * sty
            return max(0.0, float(sse)), float(intercept), float(slope)

        dp = np.full(m, np.inf)
        prev = np.full(m, -1, dtype=np.int64)
        dp[0] = -beta
        for j in range(1, m):
            b = int(nodes[j])
            for i in range(j):
                a = int(nodes[i])
                if b - a + 1 < min_len or not np.isfinite(dp[i]):
                    continue
                cost, _, _ = segment_cost(a, b)
                trial = dp[i] + cost + beta
                if trial < dp[j]:
                    dp[j] = trial
                    prev[j] = i

        if not np.isfinite(dp[-1]):
            raise FloatingPointError("no valid segmentation")

        segs = []
        j = m - 1
        while j > 0:
            i = int(prev[j])
            if i < 0:
                raise FloatingPointError("invalid predecessor")
            segs.append((int(nodes[i]), int(nodes[j])))
            j = i
        segs.reverse()

        fitted = np.empty(n, dtype=float)
        for k, (a, b) in enumerate(segs):
            _, intercept, slope = segment_cost(a, b)
            fitted[a:b + 1] = intercept + slope * t[a:b + 1]
            if k:
                fitted[a] = 0.5 * (fitted[a] + fitted[a - 1])

        if not np.all(np.isfinite(fitted)):
            raise FloatingPointError("non-finite fit")

        z = fitted - np.median(fitted)
        energy = float(np.dot(z, z))
        if energy > eps:
            xc = x - np.median(x)
            gain = float(np.clip(np.dot(z, xc) / energy, 0.85, 1.18))
            fitted = gain * fitted + float(np.median(x - gain * fitted))
        return _finite_signal(fitted)

    except Exception:
        span = min(n if n % 2 else n - 1, max(3, int(window_size) | 1))
        if _HAVE_SCIPY and span >= 5:
            return np.asarray(
                savgol_filter(x, span, min(3, span - 1), mode="interp"),
                dtype=float,
            )
        return _fallback_smoother(x, max(1, span))


def enhanced_filter_with_trend_preservation(x, window_size=20):
    x = np.asarray(x, dtype=float)
    if x.ndim != 1:
        raise ValueError("Input signal must be one-dimensional")
    if window_size < 1:
        raise ValueError("window_size must be at least 1")
    if len(x) < window_size:
        raise ValueError("Input signal length must be >= window_size")
    x = _finite_signal(x)
    if x.size <= 1:
        return x.copy()
    smooth = _piecewise_linear_filter(x, window_size)
    return _finite_signal(smooth)[window_size - 1:]


def process_signal(input_signal, window_size=20, algorithm_type="enhanced"):
    if algorithm_type == "enhanced":
        return enhanced_filter_with_trend_preservation(input_signal, window_size)
    return adaptive_filter(input_signal, window_size)


def generate_test_signal(length=1000, noise_level=0.3, seed=42):
    rng = np.random.RandomState(seed)
    t = np.linspace(0, 10, length)
    clean = (
        2 * np.sin(2 * np.pi * 0.5 * t)
        + 1.5 * np.sin(2 * np.pi * 2 * t)
        + 0.5 * np.sin(2 * np.pi * 5 * t)
        + 0.8 * np.exp(-t / 5) * np.sin(2 * np.pi * 1.5 * t)
    )
    clean += 0.1 * t * np.sin(0.2 * t)
    clean += np.cumsum(rng.randn(length) * 0.05)
    return clean + rng.normal(0, noise_level, length), clean


def run_signal_processing(noisy_signal=None, signal_length=1000,
                          noise_level=0.3, window_size=20):
    if noisy_signal is None:
        noisy_signal, clean_signal = generate_test_signal(
            signal_length, noise_level
        )
    else:
        clean_signal = None

    filtered = process_signal(noisy_signal, window_size, "enhanced")
    if clean_signal is None:
        return {
            "filtered_signal": filtered,
            "clean_signal": None,
            "noisy_signal": None,
            "correlation": 0.0,
            "noise_reduction": 0.0,
            "signal_length": len(filtered),
        }

    clean = clean_signal[window_size - 1:]
    noisy = np.asarray(noisy_signal, dtype=float)[window_size - 1:]
    m = min(len(filtered), len(clean))
    filtered, clean, noisy = filtered[:m], clean[:m], noisy[:m]
    corr = 0.0
    if m > 1 and np.std(filtered) > 0 and np.std(clean) > 0:
        corr = float(np.corrcoef(filtered, clean)[0, 1])
    before = float(np.var(noisy - clean))
    after = float(np.var(filtered - clean))
    reduction = (before - after) / before if before > 0 else 0.0
    return {
        "filtered_signal": filtered,
        "clean_signal": clean,
        "noisy_signal": noisy,
        "correlation": corr,
        "noise_reduction": reduction,
        "signal_length": m,
    }


if __name__ == "__main__":
    results = run_signal_processing()
    print("Signal processing completed!")
    print(f"Correlation with clean signal: {results['correlation']:.3f}")
    print(f"Noise reduction: {results['noise_reduction']:.3f}")
    print(f"Processed signal length: {results['signal_length']}")

